            except (OSError, subprocess.TimeoutExpired): commit = None
            snapshot = {'definition': pure_definition, 'pipeline_hash': _hash(pure_definition), 'sources': sources, 'source_content_hash': _hash([{'name': s['name'], 'sha256': s['sha256']} for s in sources]), 'code': code, 'git_commit': commit, 'step_versions': {c['type']: c['version'] for c in self.catalog()}, 'reference_source': 'Cópia imutável dos seis arquivos; cadastros do fechamento legado não são usados.', 'import_warnings': imported.get('import_warnings', [])}
            run = {'id': ident, 'run_id': ident, 'competencia': period, 'period': period, 'status': 'queued', 'pipeline_id': definition['id'], 'pipeline_version': definition['version'], 'created_at': _now(), 'created_by': actor, 'started_at': None, 'finished_at': None, 'directory': str(directory), 'snapshot': snapshot, 'datasets': {}, 'approval': None, 'exports': [], 'steps': [{'id': s['id'], 'type': s['type'], 'params': s.get('params', {}), 'status': 'pending', 'metrics': {}, 'outputs': [], 'datasets': [], 'started_at': None, 'finished_at': None} for s in pure_definition['steps']]}
            (directory / 'snapshot.json').write_text(_json(snapshot), encoding='utf-8')
