        rate["rate_pct"] = format(dec(rate["rate_pct"]).quantize(Decimal("0.0001")), "f")
    audit_sources = []
    for source in datasets["sources"]:
        full_path = source.pop("path", None)
        source["size"] = Path(full_path).stat().st_size if full_path else None
